     "prose": [
      "计算机自 1946 年 ENIAC 诞生以来，经历了电子管、晶体管、集成电路、大规模集成电路四个时代。现代计算机普遍遵循冯·诺依曼体系结构，其核心思想是\"存储程序\"——把程序和数据一同以二进制形式存入存储器，由控制器自动逐条取出并执行。",
      "从硬件看，计算机由运算器、控制器、存储器、输入设备、输出设备五大部件组成，其中运算器与控制器合称中央处理器(CPU)。存储器按速度分层为寄存器、高速缓存(Cache)、主存(内存)与外存，Cache 的作用是缓解 CPU 与内存之间的速度差异。总线分为数据总线、地址总线和控制总线，分别传输数据、地址与控制信号。",
      "计算机内部一切信息都以二进制表示。数制转换是公共基础与计算机基础的常见计算题：任意 R 进制转十进制用\"按权展开求和\"，十进制转 R 进制整数部分用\"除 R 取余、逆序排列\"。二进制与八进制、十六进制之间可按 3 位、4 位一组快速转换。",
      "字符编码方面，ASCII 码用 7 位二进制表示 128 个西文字符，其中数字 0 为 48、大写 A 为 65、小写 a 为 97。汉字需经过输入码、国标码、机内码、字形码的转换，机内码等于国标码加上 8080H。多媒体信息经数字化后存储，图像容量约等于分辨率与色彩深度的乘积，音频容量与采样频率、量化位数、声道数和时长成正比。"
     ],
