     "prose": [
      "数学与统计函数是表格中使用最频繁的一类。求和用 SUM，求平均用 AVERAGE，求最值用 MAX 和 MIN。计数函数需注意区别：COUNT 只统计数值型单元格个数，COUNTA 统计所有非空单元格个数，COUNTBLANK 统计空单元格个数，COUNTIF 则按条件计数。",
      "取整类函数包括 ROUND（四舍五入到指定位数）、ROUNDUP（向上舍入）、ROUNDDOWN（向下舍入）、INT（向下取整）和 ABS（取绝对值）。RANK 函数用于排名，语法为 RANK(数值, 区域, 序数)，第三参数为 0 或省略表示降序、非 0 表示升序。使用 RANK 时，第二个参数\"区域\"必须用绝对引用锁定，否则公式下拉填充时排名结果会出错。",
      "逻辑函数用于实现条件判断。IF 函数的语法为 IF(条件, 条件为真时的值, 条件为假时的值)，是最常用的判断函数。AND 函数要求所有条件都为真才返回真，OR 函数只要有一个条件为真就返回真，NOT 函数对条件取反。它们常与 IF 嵌套使用，例如同时判断多门课程是否及格。",
      "多级 IF 嵌套可实现分级判断，如把成绩分为\"优、良、及格、不及格\"四档，书写时判断顺序应从高到低，并注意括号的正确配对，这是最容易出错的地方。IFERROR 函数用于容错，当表达式出错（如除零、VLOOKUP 查无结果）时返回指定值；IFNA 则专门处理 #N/A 错误。善用容错函数可让报表更加整洁专业。"
     ],
